declarations.type:
∀ {Identity : Type} {window : SearchRouteAdmissionGcPublication.CycleWindow Identity}
  {publication : SearchRouteAdmissionGcPublication.RecordPublication Identity}
  {token : SearchRouteAdmissionGcPublication.BarrierToken Identity} {expectedReceiptIdentity : Identity},
  SearchRouteAdmissionGcPublication.ValidBarrierToken window publication token expectedReceiptIdentity →
    window.markEpoch ≤ window.sweepEpoch

∀ {Identity : Type} {gcCycle : SearchRouteAdmissionGcBarrier.GcCycle Identity}
  {window : SearchRouteAdmissionGcPublication.CycleWindow Identity}
  {publication : SearchRouteAdmissionGcPublication.RecordPublication Identity}
  {baselineToken extensionToken : SearchRouteAdmissionGcPublication.BarrierToken Identity},
  SearchRouteAdmissionGcPublication.PublicationBarrierCertificate gcCycle window publication baselineToken
      extensionToken →
    baselineToken.installedAt ≤ publication.publishedAt ∧
      extensionToken.installedAt ≤ publication.publishedAt ∧
        baselineToken.cycleIdentity = publication.cycleIdentity ∧
          extensionToken.cycleIdentity = publication.cycleIdentity

∀ {Identity : Type} {gcCycle : SearchRouteAdmissionGcBarrier.GcCycle Identity}
  {window : SearchRouteAdmissionGcPublication.CycleWindow Identity}
  {publication : SearchRouteAdmissionGcPublication.RecordPublication Identity}
  {baselineToken extensionToken : SearchRouteAdmissionGcPublication.BarrierToken Identity},
  SearchRouteAdmissionGcPublication.PublicationBarrierCertificate gcCycle window publication baselineToken
      extensionToken →
    SearchRouteAdmissionGcBarrier.ConcurrentCommitCertificate gcCycle publication.publishedAt publication.record
